{
  "findings": [
    {
      "ref": "[D521]",
      "area": "contact",
      "claim": "A parent reports that strangers can message or voice chat with your child in Google Classroom.",
      "stance": "risk",
      "quote": "Kids can interact with other students and even teachers by text and video using Hangouts or the chat function in Meet."
    },
    {
      "ref": "[D521]",
      "area": "money",
      "claim": "The platform does not push in-app purchases, loot boxes, pay-to-win or subscription traps.",
      "stance": "neutral",
      "quote": "Google Classroom is a class-organization platform that incorporates Google's core products (Google Docs, Sheets, Slides, Drive, etc.) so students can access everything they need for a class, including homework assignments, group projects, files, and even Google Hangouts to chat with the teacher or the entire class."
    },
    {
      "ref": "[D521]",
      "area": "data",
      "claim": "Google can collect student data from some of the Classroom tools, such as YouTube, if they're enabled.",
      "stance": "risk",
      "quote": "Google Classroom does invite some risks, including data tracking, potential contact with strangers, and even cyberbullying. While Google has stricter privacy practices for its educational apps, it can collect student data from some of the Classroom tools, such as YouTube, if they're enabled."
    },
    {
      "ref": "[D521]",
      "area": "age_gating",
      "claim": "A parent reports that the age gate does not work in practice; children of any age can join classes.",
      "stance": "risk",
      "quote": "Your kid may use their personal Google account to access Classroom -- but they're not supposed to use it for school."
    },
    {
      "ref": "[D521]",
      "area": "content",
      "claim": "A parent reports that cyberbullying can occur in shared Google Docs used for group projects.",
      "stance": "risk",
      "quote": "There have also been some reports of kids cyberbullying other students in Google Docs shared for group projects -- partly because it's a place no one would think to look for that kind of behavior."
    },
    {
      "ref": "[D521]",
      "area": "developer_record",
      "claim": "The developer has not been reported to have fines, breaches, lawsuits or regulatory actions.",
      "stance": "neutral",
      "quote": "Google has stricter privacy practices for its educational apps, but no specific regulatory actions are mentioned."
    }
  ]
}
